//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn put_level(value: *mut i32) -> bool;
  fn put_boolean_value(value: *mut bool) -> bool;
  fn put_character_value(value: *mut u8) -> bool;
  fn put_signed_8_value(value: *mut i8) -> bool;
  fn put_signed_16_value(value: *mut i16) -> bool;
  fn put_unsigned_8_value(value: *mut u8) -> bool;
  fn put_unsigned_16_value(value: *mut u16) -> bool;
  fn put_sample(value: *mut i32) -> bool;
  fn put_flag(value: *mut bool) -> bool;
  fn put_operating_state(value: *mut Exhaustive_Monitor::OperatingState) -> bool;
  fn put_samples(value: *mut Exhaustive_Monitor::Samples) -> bool;
  fn put_telemetry(value: *mut Exhaustive_Monitor::Telemetry_i) -> bool;
  fn put_pulse() -> bool;
}

pub fn unsafe_put_level(value: &i32) -> bool
{
  unsafe {
    return put_level(value as *const i32 as *mut i32);
  }
}

pub fn unsafe_put_boolean_value(value: &bool) -> bool
{
  unsafe {
    return put_boolean_value(value as *const bool as *mut bool);
  }
}

pub fn unsafe_put_character_value(value: &u8) -> bool
{
  unsafe {
    return put_character_value(value as *const u8 as *mut u8);
  }
}

