#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref OUT_level: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref OUT_boolean_value: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_character_value: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref OUT_signed_8_value: Mutex<Option<i8>> = Mutex::new(None);
  pub static ref OUT_signed_16_value: Mutex<Option<i16>> = Mutex::new(None);
  pub static ref OUT_unsigned_8_value: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref OUT_unsigned_16_value: Mutex<Option<u16>> = Mutex::new(None);
  pub static ref OUT_sample: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref OUT_flag: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_operating_state: Mutex<Option<Exhaustive_Monitor::OperatingState>> = Mutex::new(None);
  pub static ref OUT_samples: Mutex<Option<Exhaustive_Monitor::Samples>> = Mutex::new(None);
  pub static ref OUT_telemetry: Mutex<Option<Exhaustive_Monitor::Telemetry_i>> = Mutex::new(None);
  pub static ref OUT_pulse: Mutex<Option<u8>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *OUT_level.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_boolean_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_character_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_signed_8_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_signed_16_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_unsigned_8_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_unsigned_16_value.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_sample.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_flag.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_operating_state.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_samples.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_telemetry.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_pulse.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn put_level(value: *mut i32) -> bool
{
  unsafe {
    *OUT_level.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

